  textUser: 'Topic: ' + (article.Topic || '') + '\nDescription: ' + (article.Description || '') + linkInfo + '\nCurrent date: ' + today,
  imageSystem: prompts.ArticleImage || '',
  imageUser: 'Topic: ' + (article.Topic || '') + '\nDescription: ' + (article.Description || ''),
  metaSeoSystem: prompts.ArticleMetaSEO || '',
