const crypto = require('crypto');
const https = require('https');
const http = require('http');
const { URL } = require('url');

function httpPost(urlStr, headers, body) {
  return new Promise((resolve, reject) => {
    const u = new URL(urlStr);
    const mod = u.protocol === 'https:' ? https : http;
    const opts = { method: 'POST', hostname: u.hostname, port: u.port || (u.protocol === 'https:' ? 443 : 80), path: u.pathname + u.search, headers };
    const req = mod.request(opts, (res) => {
      const chunks = [];
      res.on('data', (c) => chunks.push(c));
      res.on('end', () => resolve({ status: res.statusCode, body: Buffer.concat(chunks).toString() }));
    });
    req.on('error', reject);
    req.setTimeout(120000, () => { req.destroy(); reject(new Error('Timeout')); });
    if (body) req.write(body);
    req.end();
  });
}

const imageSystemPrompt = $('Prepare Prompts').first().json.imageSystem || '';
const imagePromptBase = $('Prepare Prompts').first().json.imageUser || '';
const title = $('Generate Title').first().json.message.content.trim();
const imagePrompt = imagePromptBase + '\n\nArticle title: ' + title;
let featureImageUrl = '';
try {
  const apiUrl = '{{LLM_API_URL}}';
  const apiKey = '{{LLM_API_KEY}}';
  const imageModel = '{{LLM_IMAGE_MODEL}}';
  if (!apiUrl || !apiKey || !imageModel) throw new Error('Missing LLM image config');
  const llmBody = JSON.stringify({ model: imageModel, messages: [{ role: 'system', content: imageSystemPrompt }, { role: 'user', content: imagePrompt }], modalities: ['text', 'image'], image_config: { image_size: '1K', aspect_ratio: '1:1' } });
  const llmRes = await httpPost(apiUrl + '/chat/completions', {
    'Content-Type': 'application/json',
    'Authorization': 'Bearer ' + apiKey,
    'Content-Length': Buffer.byteLength(llmBody),
  }, llmBody);
  if (llmRes.status !== 200) throw new Error('LLM API: ' + llmRes.status);
  const llmData = JSON.parse(llmRes.body);
  llmRes.body = null;
  let base64Data = '';
  let mimeType = 'image/png';
  const msg = llmData.choices?.[0]?.message;
  const images = msg?.images;
  if (Array.isArray(images) && images.length > 0) {
    const imgObj = images[0];
    const imgUrl = typeof imgObj.image_url === 'object' ? imgObj.image_url.url : (typeof imgObj.image_url === 'string' ? imgObj.image_url : '');
    if (imgUrl) {
      const m = imgUrl.match(/^data:(image\/[a-z]+);base64,(.+)/s);
      if (m) { mimeType = m[1]; base64Data = m[2]; }
    }
  }
  if (!base64Data) {
    const content = msg?.content;
    if (Array.isArray(content)) {
      for (const part of content) {
        if (part.type === 'image_url' && part.image_url?.url) {
          const m = part.image_url.url.match(/^data:(image\/[a-z]+);base64,(.+)/s);
          if (m) { mimeType = m[1]; base64Data = m[2]; break; }
        }
      }
    } else if (typeof content === 'string') {
      const m = content.match(/data:(image\/[a-z]+);base64,([A-Za-z0-9+\/=]+)/);
      if (m) { mimeType = m[1]; base64Data = m[2]; }
    }
  }
  if (!base64Data) throw new Error('No image data in LLM response');
  const ghostKey = '{{GHOST_ADMIN_API_KEY}}';
  const [kid, secret] = ghostKey.split(':');
  const hdr = Buffer.from(JSON.stringify({alg:'HS256',typ:'JWT',kid})).toString('base64url');
  const now = Math.floor(Date.now()/1000);
  const pay = Buffer.from(JSON.stringify({iat:now,exp:now+300,aud:'/admin/'})).toString('base64url');
  const hmac = crypto.createHmac('sha256', Buffer.from(secret, 'hex'));
  hmac.update(hdr + '.' + pay);
  const jwt = hdr + '.' + pay + '.' + hmac.digest('base64url');
  const imageBuffer = Buffer.from(base64Data, 'base64');
  base64Data = '';
  const ext = mimeType === 'image/jpeg' ? 'jpg' : 'png';
  const boundary = '----n8n' + Date.now();
  const formBody = Buffer.concat([
    Buffer.from('--' + boundary + '\r\nContent-Disposition: form-data; name="file"; filename="article.' + ext + '"\r\nContent-Type: ' + mimeType + '\r\n\r\n'),
    imageBuffer,
    Buffer.from('\r\n--' + boundary + '\r\nContent-Disposition: form-data; name="purpose"\r\nContent-Type: text/plain\r\n\r\nimage\r\n--' + boundary + '--\r\n'),
  ]);
  const ghostRes = await httpPost('{{GHOST_API_URL}}/ghost/api/admin/images/upload/', {
    'Authorization': 'Ghost ' + jwt,
    'Content-Type': 'multipart/form-data; boundary=' + boundary,
    'Content-Length': formBody.length,
  }, formBody);
  if (ghostRes.status === 201 || ghostRes.status === 200) {
    const gd = JSON.parse(ghostRes.body);
    featureImageUrl = gd.images?.[0]?.url || '';
  } else { throw new Error('Ghost upload: ' + ghostRes.status); }
} catch (e) {
  console.log('Image generation skipped:', e.message);
}
return [{ json: { featureImageUrl } }];

const crypto = require('crypto');
const key = '{{GHOST_ADMIN_API_KEY}}';
const [id, secret] = key.split(':');
const header = Buffer.from(JSON.stringify({alg:'HS256',typ:'JWT',kid:id})).toString('base64url');
const now = Math.floor(Date.now()/1000);
const payload = Buffer.from(JSON.stringify({iat:now,exp:now+300,aud:'/admin/'})).toString('base64url');
const hmac = crypto.createHmac('sha256', Buffer.from(secret, 'hex'));
hmac.update(`${header}.${payload}`);
const sig = hmac.digest('base64url');
const jwt = `${header}.${payload}.${sig}`;
const articleTitle = $('Generate Title').first().json.message.content.trim();
let articleHtml = $('Generate Article').first().json.message.content;
articleHtml = articleHtml.replace(/^```html?\n?/i, '').replace(/\n?```\s*$/, '').trim();
// Extract FAQ pairs BEFORE wrap-loose-text (wrapping inserts empty <p> between h3 and p)
const faqRegex = /<h3[^>]*>(.*?)<\/h3>\s*<p[^>]*>(.*?)<\/p>/gs;
const faqs = [];
let faqMatch;
while ((faqMatch = faqRegex.exec(articleHtml)) !== null) {
  const q = faqMatch[1].replace(/<[^>]*>/g, '').trim();
  const a = faqMatch[2].replace(/<[^>]*>/g, '').trim();
  if (q && a) faqs.push({ '@type': 'Question', name: q, acceptedAnswer: { '@type': 'Answer', text: a } });
}
let faqSchemaTag = '';
if (faqs.length > 0) {
  faqSchemaTag = '<script type="application/ld+json">' + JSON.stringify({ '@context': 'https://schema.org', '@type': 'FAQPage', mainEntity: faqs }) + '</script>';
}
// Wrap loose text (not inside block tags) in <p> tags
articleHtml = articleHtml.replace(/(<\/(h[1-6]|ul|ol|blockquote|div|table|pre|hr)>)\s*([^<]+?)\s*(?=<(h[1-6]|ul|ol|blockquote|div|table|pre|hr|p|$))/gi, (m, closeTag, t1, text, t2) => text.trim() ? closeTag + '\n<p>' + text.trim() + '</p>\n' : m);
// Wrap leading bare text before the first block tag
articleHtml = articleHtml.replace(/^([^<]+?)(?=<(h[1-6]|ul|ol|blockquote|div|table|pre|hr|p))/, (m, text) => text.trim() ? '<p>' + text.trim() + '</p>\n' : m);
// Parse meta from LLM response (may not exist if Generate Meta failed)
let metaTitle = articleTitle;
let metaDescription = '';
let tags = [];
try {
  const metaNode = $('Generate Meta');
  if (metaNode && metaNode.first() && metaNode.first().json && metaNode.first().json.message) {
    const metaRaw = metaNode.first().json.message.content.trim();
    const cleaned = metaRaw.replace(/^```json?\n?/i, '').replace(/\n?```\s*$/, '');
    const metaJson = JSON.parse(cleaned);
    if (metaJson.meta_title) metaTitle = metaJson.meta_title.substring(0, 60);
    if (metaJson.meta_description) metaDescription = metaJson.meta_description.substring(0, 155);
    if (Array.isArray(metaJson.tags)) {
      tags = metaJson.tags.filter(t => typeof t === 'string' && t.trim()).map(t => t.trim().substring(0, 191)).slice(0, 10);
    }
  }
} catch(e) { /* fallback to article title */ }
const topic = $('Get Next Queued').first().json.list[0].Topic || '';
const featureImageUrl = $('Generate & Upload Image').first().json.featureImageUrl || '';
return [{ json: { jwt, articleTitle, articleHtml, featureImageUrl, metaTitle, metaDescription, topic, tags, faqSchemaTag } }];

