const prompts = $('Get Prompts (retry)').first().json.list[0];
const article = $('Get Next Queued').first().json.list[0];

// Resolve "latest" to actual Ghost article URL
if (article.ArticleURL && article.ArticleURL.toLowerCase() === 'latest') {
  const key = '{{GHOST_ADMIN_API_KEY}}';
  const [kid, secret] = key.split(':');
  const header = Buffer.from(JSON.stringify({alg:'HS256',typ:'JWT',kid})).toString('base64url');
  const now = Math.floor(Date.now()/1000);
  const payload = Buffer.from(JSON.stringify({iat:now,exp:now+300,aud:'/admin/'})).toString('base64url');
  const hmac = crypto.createHmac('sha256', Buffer.from(secret, 'hex'));
  hmac.update(header + '.' + payload);
  const sig = hmac.digest('base64url');
  const jwt = header + '.' + payload + '.' + sig;

  const ghostRes = await httpReq(
    '{{GHOST_API_URL}}/ghost/api/admin/posts/?limit=1&order=published_at%20desc&filter=status:published&fields=slug,url',
    'GET', { 'Authorization': 'Ghost ' + jwt }
  );
  if (ghostRes.status !== 200) throw new Error('Ghost API error: ' + ghostRes.status);
  const ghostData = JSON.parse(ghostRes.body);
  if (!ghostData.posts || ghostData.posts.length === 0) {
    throw new Error('No published articles found \u2014 cannot resolve "latest"');
  }
  article.ArticleURL = ghostData.posts[0].url;

  // Update NocoDB so user sees which article was used
  const patchBody = JSON.stringify({ Id: article.Id, ArticleURL: article.ArticleURL });
  await httpReq(
    'http://nocodb:8080/api/v2/tables/{{NOCODB_TABLE_ID}}/records',
    'PATCH',
    { 'Content-Type': 'application/json', 'xc-token': '{{NOCODB_AUTH_TOKEN}}', 'Content-Length': Buffer.byteLength(patchBody) },
    patchBody
  );
}

